import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.XxxS7AoL.js";const k=JSON.parse('{"title":"App Mode","description":"","frontmatter":{},"headers":[],"relativePath":"app-mode.md","filePath":"app-mode.md","lastUpdated":null}'),o={name:"app-mode.md"};function n(h,e,r,l,p,d){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="App-Mode" tabindex="-1">App Mode <a class="header-anchor" href="#App-Mode" aria-label="Permalink to &quot;App Mode {#App-Mode}&quot;">​</a></h1><p>Slate&#39;s normal posture is an <strong>authoring</strong> environment: every cell is editable, the agent is a click away, and the package tree is reachable from the Files panel. That is exactly wrong when the audience is a domain expert who was handed a URL and told to use the tool. They need the controls and the results — and nothing that can put the document into a state they can&#39;t recover from.</p><p>App mode is that second posture. The notebook still runs live: sliders move, fits recompute, figures redraw. What&#39;s gone is everything that edits it.</p><p><img class="slate-shot" src="https://github.com/kahliburke/KaimonSlate.jl/releases/download/docs-assets/app-view.png" alt=""></p><h2 id="Serving-an-existing-notebook-as-an-app" tabindex="-1">Serving an existing notebook as an app <a class="header-anchor" href="#Serving-an-existing-notebook-as-an-app" aria-label="Permalink to &quot;Serving an existing notebook as an app {#Serving-an-existing-notebook-as-an-app}&quot;">​</a></h2><p>App mode is a property of the <strong>process</strong>, not of the document. A hub started with <code>app = true</code> serves its notebooks as applications and refuses the authoring API outright:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> KaimonSlate</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">hub </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> start_hub</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(; host </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;127.0.0.1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, port </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8080</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, app </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">open_notebook!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(hub, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;notebooks/analysis.jl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>It is deliberately <em>not</em> a per-notebook footer flag. A document attribute is something an author edits by accident, and &quot;can this request mutate my notebook?&quot; should not depend on a token inside the file being served.</p><p>To preview the app view while authoring, append <code>?app=1</code> to a notebook URL on an ordinary hub. That gives you the same <strong>view</strong> with none of the enforcement — useful for checking layout, not for handing out.</p><h2 id="Shipping-an-app-to-someone-else" tabindex="-1">Shipping an app to someone else <a class="header-anchor" href="#Shipping-an-app-to-someone-else" aria-label="Permalink to &quot;Shipping an app to someone else {#Shipping-an-app-to-someone-else}&quot;">​</a></h2><p><a href="/KaimonSlate.jl/previews/PR32/api#KaimonSlate.NotebookServer.export_app"><code>export_app</code></a> writes a self-contained folder you can copy to whichever machine will run it:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">export_app</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(nb, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dist/band-deconvolution&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; title </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;band-deconvolution&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, port </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 7373</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>The folder holds the notebook&#39;s reproducible bundle plus launchers. The recipient needs only Julia 1.10+:</p><table tabindex="0"><thead><tr><th style="text-align:right;"></th><th style="text-align:right;"></th></tr></thead><tbody><tr><td style="text-align:right;">macOS / Linux</td><td style="text-align:right;"><code>./run.sh</code></td></tr><tr><td style="text-align:right;">Windows</td><td style="text-align:right;">double-click <code>run.bat</code></td></tr><tr><td style="text-align:right;">any</td><td style="text-align:right;"><code>julia run.jl</code></td></tr></tbody></table><p>The first run installs the application&#39;s packages and precompiles them — several minutes is normal. Later starts are fast. Nothing waits on stdin, so it also runs unattended under systemd, in a container, or as <code>nohup ./run.sh &amp;</code>.</p><p>That first run needs network access. It fetches Slate itself into a shared environment and instantiates the notebook&#39;s manifest. Once that has happened the app starts offline.</p><p>An app is not a separate export format. It <strong>is</strong> the standalone bundle; &quot;app&quot; is a posture the launcher takes. Which is also why updating a deployed app is <code>export_app</code> again over the same folder — the install detects that the bundle beside it has changed and refreshes in place, keeping whatever the app accumulated next to it (its <code>datadir()</code>, saved results, caches).</p><h3 id="What-ships" tabindex="-1">What ships <a class="header-anchor" href="#What-ships" aria-label="Permalink to &quot;What ships {#What-ships}&quot;">​</a></h3><p>By default, the project&#39;s git-<strong>tracked</strong> files. That&#39;s the right default: it carries the source and leaves out build output, scratch and stray artifacts.</p><p><code>include</code> names extra project-relative paths to carry anyway. Reach for it when part of the app is deliberately untracked — the common case being reference data under the notebook&#39;s <code>datadir()</code>, which is git-ignored <em>by construction</em> (that directory self-ignores so a stray database is never committed). An app whose samples live there arrives unable to load them:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">export_app</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(nb, dir; include </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;assets/spectra&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">])</span></span></code></pre></div><p>A project with <strong>no commits</strong> has no tracked files at all, so the bundle falls back to a partial copy. <code>export_app</code> warns when it sees that, because the result looks fine until it is deployed.</p><h3 id="Cells-that-run-on-a-region" tabindex="-1">Cells that run on a region <a class="header-anchor" href="#Cells-that-run-on-a-region" aria-label="Permalink to &quot;Cells that run on a region {#Cells-that-run-on-a-region}&quot;">​</a></h3><p>A cell tagged <code>region=&lt;name&gt;</code> runs on a named compute target. The tag travels in the notebook, but the <em>definition</em> — host, transport — lives in your region registry, and an app keeps its own state home rather than reading yours. So <code>export_app</code> writes the definitions the notebook actually uses into a <code>regions.json</code> beside the launcher, and <code>run.jl</code> seeds them into the app&#39;s home on first start. Nothing else from your registry travels.</p><p>Two things follow, and <code>export_app</code> logs the hosts it embedded so neither is a surprise:</p><ul><li><p><strong>The host name is in the exported folder.</strong> No keys or credentials travel, but if you hand the app to someone they can read where its region cells run. Untag the cells if that matters.</p></li><li><p><strong>The app needs to reach that host itself</strong>, over SSH, as whoever runs it. On your own machine that already works. Elsewhere it will not, and the cell reports that it could not be placed rather than appearing to hang.</p></li></ul><p>An operator can point the app somewhere else: define the same region name in the app&#39;s own home and it is used as-is — seeding only fills a home that has no registry of its own.</p><h2 id="Presentation-defaults" tabindex="-1">Presentation defaults <a class="header-anchor" href="#Presentation-defaults" aria-label="Permalink to &quot;Presentation defaults {#Presentation-defaults}&quot;">​</a></h2><p><a href="/KaimonSlate.jl/previews/PR32/api#KaimonSlate.NotebookServer.app_defaults"><code>app_defaults</code></a> sets what a visitor sees <em>before</em> expressing a preference of their own:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">export_app</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(nb, dir; appdefaults </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> app_defaults</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(theme </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;midnight&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, pagewidth </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1400</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span></code></pre></div><p>These are defaults, not enforcement. A visitor who has chosen keeps their choice — the app&#39;s settings popover offers the same reader-facing subset (theme, page width, and the <a href="/KaimonSlate.jl/previews/PR32/settings#Chart-renderer">chart renderer</a>), and <code>localStorage</code> still wins.</p><h2 id="Workbook-mode" tabindex="-1">Workbook mode <a class="header-anchor" href="#Workbook-mode" aria-label="Permalink to &quot;Workbook mode {#Workbook-mode}&quot;">​</a></h2><p>A course notebook is an app in every respect but one: some cells are the reader&#39;s to write. Workbook mode opens exactly those cells and leaves the rest of the document read-only.</p><p>Mark a cell by adding the <code>workbook</code> tag to its header:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#%% code id=ex_double workbook</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> double</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(x)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    missing</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">end</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#%% code id=try_double workbook</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">double</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">21</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#%% code id=chk_double</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">isequal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">double</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">21</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">42</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>The check cell carries no tag, so the reader cannot rewrite the test that grades them. It uses <code>isequal</code> because an unimplemented stub returns <code>missing</code>.</p><p>There is no checkbox for <code>workbook</code> in the 🏷 tag popover. Type it into the <code>#%%</code> header, or add it through the popover&#39;s &quot;add custom tag&quot; input.</p><h3 id="Serving-one" tabindex="-1">Serving one <a class="header-anchor" href="#Serving-one" aria-label="Permalink to &quot;Serving one {#Serving-one}&quot;">​</a></h3><p>Workbook mode is a property of the process, like app mode, and it is refused without it:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">hub </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> start_hub</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(; port </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8080</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, app </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, workbook </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p><code>workbook = true</code> on its own throws. A document can never turn an ordinary hub into a workbook by carrying a tag.</p><p>To ship one, tick <strong>Workbook</strong> in the Export dialog&#39;s App format, or pass the keyword:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">export_app</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(nb, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dist/exercises&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; workbook </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Preview either posture while authoring by appending <code>?app=1</code> or <code>?app=1&amp;workbook=1</code> to a notebook URL. As with the app preview, that gives you the view and none of the enforcement.</p><p><img class="slate-shot" src="https://github.com/kahliburke/KaimonSlate.jl/releases/download/docs-assets/app-workbook.png" alt=""></p><h3 id="What-the-reader-gets" tabindex="-1">What the reader gets <a class="header-anchor" href="#What-the-reader-gets" aria-label="Permalink to &quot;What the reader gets {#What-the-reader-gets}&quot;">​</a></h3><p>Tagged cells come back as editors, framed and labelled &quot;your turn&quot;. Each one has <strong>Run</strong> and <strong>Reset to the original</strong>. Running an exercise also saves it, so the reader&#39;s work survives a reload.</p><p><img class="slate-shot" src="https://github.com/kahliburke/KaimonSlate.jl/releases/download/docs-assets/workbook-cell.png" alt=""></p><p>They also get a scratchpad for working out an answer before committing it (⌘⇧S, or the floating 🧪 launcher), which never touches the document. The command palette returns with a reader-only command list: search the docs, settings, scratchpad, table of contents, run stale cells, jump to a cell. Editor preferences (keymap, syntax theme, wrap) appear in the settings popover.</p><p><strong>Reset</strong> restores the cell as the author shipped it. That original has to be stored separately, because saving a workbook is the ordinary notebook save and the reader&#39;s answers overwrite the served <code>.jl</code>. <code>export_app</code> writes a second pristine copy of the bundle into the folder and points the launcher at it, which roughly doubles the exported folder&#39;s size. Serving a workbook by hand instead of from an export needs the same copy, either at <code>SLATE_WORKBOOK_ORIGINAL</code> or as a sibling <code>.&lt;notebook&gt;.jl.original</code>. Without one, Reset reports that it has no original on file.</p><h3 id="A-workbook-is-not-a-sandbox" tabindex="-1">A workbook is not a sandbox <a class="header-anchor" href="#A-workbook-is-not-a-sandbox" aria-label="Permalink to &quot;A workbook is not a sandbox {#A-workbook-is-not-a-sandbox}&quot;">​</a></h3><p>A workbook reader runs their own code in the notebook&#39;s Julia worker. That is the point of the exercise, and it means the reader has arbitrary code execution with that process&#39;s filesystem, network and credentials. The scratchpad grants the same thing with no cell check at all.</p><p>Combined with <a href="/KaimonSlate.jl/previews/PR32/app-mode#Access-control">there being no authentication</a> and <code>run.jl</code> binding <code>0.0.0.0</code> by default, a workbook on a shared address is a remote shell for anyone who can reach the port.</p><p>There is also one document and one worker. Two readers on the same deployed workbook overwrite each other&#39;s answers. The deployment this is built for is one bundle per reader, running on their own machine, where they could equally well open a REPL.</p><h2 id="What-a-visitor-cannot-do" tabindex="-1">What a visitor cannot do <a class="header-anchor" href="#What-a-visitor-cannot-do" aria-label="Permalink to &quot;What a visitor cannot do {#What-a-visitor-cannot-do}&quot;">​</a></h2><p>The lockdown is a server-side <strong>allowlist</strong> of <code>(method, path)</code> patterns, not a list of dangerous routes to exclude. A denylist over ~130 routes is a standing invitation to a miss: every new authoring endpoint would be reachable until someone remembered to exclude it, and the failure would be silent. An allowlist fails the other way — a new route is unreachable in app mode until it is deliberately added, which is the direction a lockdown should fail in.</p><p>So a visitor cannot edit a cell, install a package, reach the filesystem, talk to the agent, or publish, because <strong>those routes are not served at all</strong> — not merely hidden in the UI.</p><p>A workbook widens that allowlist by seven routes: edit one cell, run, completions, the two scratchpad routes, fetch a cell&#39;s original, and docstring lookup and search. Reaching a route is not authority to use it. The cell id rides in the path, and the two routes that take one check it against the document&#39;s <code>workbook</code> tags before doing anything. A request for an untagged cell is refused with a 403 naming the route.</p><p>The agent is off by default. Pass <code>agent = true</code> to <code>export_app</code> if an app&#39;s readers genuinely need it. The Export dialog cannot turn it on, so that path is the Julia function only.</p><h2 id="Getting-data-in-and-out" tabindex="-1">Getting data in and out <a class="header-anchor" href="#Getting-data-in-and-out" aria-label="Permalink to &quot;Getting data in and out {#Getting-data-in-and-out}&quot;">​</a></h2><p><a href="./widgets"><code>FileUpload</code></a> is how a reader gets data in: the file lands in the notebook&#39;s <a href="/KaimonSlate.jl/previews/PR32/project-files#The-data-directory">data directory</a> and binds as a path your cells can read. It is one of the few write paths app mode allows.</p><p><a href="/KaimonSlate.jl/previews/PR32/live-updates#Writing-files-out"><code>download_button</code></a> is how they leave with a result. An app&#39;s reader has no cell to run and no filesystem to look in, so anything they are meant to keep needs an explicit way out. It works live, in a static export, and on a published page.</p><h2 id="Access-control" tabindex="-1">Access control <a class="header-anchor" href="#Access-control" aria-label="Permalink to &quot;Access control {#Access-control}&quot;">​</a></h2><p>There is <strong>no authentication</strong>, at any bind address. Anything that can reach the port can drive the app and read its results. Treat &quot;who can reach this port&quot; as the entire access-control story.</p><p><code>run.jl</code> binds <code>0.0.0.0</code> by default — reachable from the whole network, which is the point of putting it on a shared lab machine, and which also means nothing stands between the network and the app. Bind it to one machine with:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./run.sh --host 127.0.0.1 --port 9000</span></span></code></pre></div><table tabindex="0"><thead><tr><th style="text-align:right;">variable</th><th style="text-align:right;">what it does</th></tr></thead><tbody><tr><td style="text-align:right;"><code>--port</code> / <code>SLATE_PORT</code></td><td style="text-align:right;">the port to serve on</td></tr><tr><td style="text-align:right;"><code>--host</code> / <code>SLATE_HOST</code></td><td style="text-align:right;">the address to bind</td></tr><tr><td style="text-align:right;"><code>SLATE_ALLOWED_HOSTS</code></td><td style="text-align:right;">extra names people will type (a DNS alias, a proxy); this machine&#39;s own names are admitted automatically</td></tr><tr><td style="text-align:right;"><code>SLATE_INSTALL_DIR</code></td><td style="text-align:right;">where to unpack the application (default: <code>.app</code> beside the launcher)</td></tr></tbody></table><h2 id="When-something-goes-wrong" tabindex="-1">When something goes wrong <a class="header-anchor" href="#When-something-goes-wrong" aria-label="Permalink to &quot;When something goes wrong {#When-something-goes-wrong}&quot;">​</a></h2><p>Open <code>/status</code> on the same address. The operator page shows whether the server and its worker process are healthy, how long they&#39;ve been up, how much memory they are using, any step that failed with its error message, and the worker&#39;s log. It is one of the few non-notebook routes app mode serves, because the person running the app is often not the person who wrote it.</p><h2 id="See-also" tabindex="-1">See also <a class="header-anchor" href="#See-also" aria-label="Permalink to &quot;See also {#See-also}&quot;">​</a></h2><ul><li><p><a href="./export">Export</a> — static HTML, PDF and the standalone <code>.jl</code> bundle this builds on</p></li><li><p><a href="./replay">Offline interactivity</a> — keeping controls working with no server at all, which is the other way to hand someone a document they can drive</p></li><li><p><a href="./publishing">Publishing</a> — putting a rendered document on the web, for reading rather than use</p></li><li><p><a href="./widgets">Widgets &amp; <code>@bind</code></a> — the controls an app&#39;s visitor drives</p></li></ul>`,71)])])}const g=t(o,[["render",n]]);export{k as __pageData,g as default};
